WITH attributed AS (SELECT s.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions s LEFT JOIN promotions pr ON s.channel = pr.channel AND s.ends_on >= pr.starts_on AND s.ends_on <= DATE_ADD(pr.ends_on, 3)) SELECT id, channel, promo_code, starts_on, promo_id, promotion_discount_pct, CASE WHEN promo_code RLIKE '^(BUNDLE|SPRING10)$' THEN 'CORE' WHEN promo_code RLIKE '^(VIP|WELCOME5)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS promo_code_zone FROM attributed;
